function lessonData(id) {
  const [pi, name, desc, lessons] = phases.find(p => p[0] === id.split('-')[0]) || phases[0];
  return lessons.map((title, i) => {
    const lid = `${pi}-${i+1}`;
    const rawD = detailed[lid] || {};
    const rawX = learningExperiences[lid];
    // Curriculum pruning can change the title attached to an existing numeric slot.
    // Never reuse old content just because the lesson ID matches: that creates silent topic mismatches.
    const norm = v => String(v || '').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
    const titleTokens = norm(title).split(' ').filter(t => t.length > 3);
    const xTitle = norm(rawX?.title || '').replace(/ mission$/,'');
    const contentMatches = rawX && (xTitle === norm(title) || titleTokens.filter(t => xTitle.includes(t)).length >= Math.max(1, Math.ceil(titleTokens.length * 0.6)));
    const d = contentMatches ? rawD : {};
    const x = contentMatches ? rawX : null;
    return {id:lid, phase:pi, phaseName:name, title, summary:d.summary || x?.summary || `Understand ${title.toLowerCase()} as an engineering capability, then apply it to a small realistic problem.`, body:d.body || x?.body || `Learn the mental model for ${title.toLowerCase()}, inspect a minimal implementation, and connect the concept to a real AI system.`, takeaways:d.takeaways || x?.takeaways || ['Explain the core idea in your own words.','Implement or inspect a minimal example.','Test a meaningful edge case or failure.','Connect the concept to a later AI system.'], code:d.code || x?.code || `# ${title}
print("Start with a small, inspectable experiment.")`, experience:x || {type:'Build',title:`${title} engineering task`,task:`Apply ${title.toLowerCase()} to a small, realistic problem. State the expected behavior before execution, then test one meaningful failure case.`,evidence:'Show the result, the failure case and the engineering decision you made.',breakIt:'Change one important assumption, observe the behavior change, and explain the root cause.'}, mistakes:d.mistakes || x?.mistakes || ['Skipping the prerequisite concept.','Copying code without understanding intermediate behavior.','Checking only whether code runs instead of whether it is correct.'], resources:(d.resources || x?.resources || []).filter(r => r && /^https?:\/\//.test(r.url)), gallery:d.gallery || x?.gallery || null, competency:competencyMeta[lid] || {difficulty:'Core',time:'30–45 min',artifact:'Short evidence note or runnable result',prerequisites:[],success:['The learner can reproduce the core behavior','The learner can explain why it works','The learner can diagnose one failure mode'],failureMode:'Change one assumption and explain the resulting failure.'}, originalVisual:(pi==='14' ? `assets/agent-systems-original/agent-${String(i+1).padStart(2,'0')}.svg` : null)};
  });
}
function phaseLessons(phaseId) { return lessonData(`${phaseId}-1`); }
